using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;

namespace ContosoUniversity.Tests
{
    /// <summary>
    /// Creates a fresh in-memory SchoolContext for each test.
    /// </summary>
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        /// <summary>
        /// Seeds the context with a minimal set of related entities useful for controller tests.
        /// </summary>
        public static SchoolContext CreateSeeded(string dbName = null)
        {
            var context = Create(dbName);

            var instructor1 = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = new DateTime(1995, 3, 11),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" }
            };
            var instructor2 = new Instructor
            {
                FirstMidName = "Fadi",
                LastName = "Fakhouri",
                HireDate = new DateTime(2002, 7, 6),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };

            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();

            var dept1 = new Department
            {
                Name = "English",
                Budget = 350000,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = instructor1.ID,
                RowVersion = new byte[] { 0, 0, 0, 1 }
            };
            var dept2 = new Department
            {
                Name = "Mathematics",
                Budget = 100000,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = instructor2.ID,
                RowVersion = new byte[] { 0, 0, 0, 2 }
            };

            context.Departments.AddRange(dept1, dept2);
            context.SaveChanges();

            var course1 = new Course
            {
                CourseID = 2021,
                Title = "Composition",
                Credits = 3,
                DepartmentID = dept1.DepartmentID,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 1045,
                Title = "Calculus",
                Credits = 4,
                DepartmentID = dept2.DepartmentID,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };

            context.Courses.AddRange(course1, course2);
            context.SaveChanges();

            // Wire up course assignments
            var ca1 = new CourseAssignment { CourseID = course1.CourseID, InstructorID = instructor1.ID };
            context.CourseAssignments.Add(ca1);
            instructor1.CourseAssignments.Add(ca1);
            context.SaveChanges();

            var student1 = new Student
            {
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = new DateTime(2010, 9, 1)
            };
            var student2 = new Student
            {
                FirstMidName = "Meredith",
                LastName = "Alonso",
                EnrollmentDate = new DateTime(2012, 9, 1)
            };
            var student3 = new Student
            {
                FirstMidName = "Arturo",
                LastName = "Anand",
                EnrollmentDate = new DateTime(2013, 9, 1)
            };

            context.Students.AddRange(student1, student2, student3);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                StudentID = student1.ID,
                CourseID = course1.CourseID,
                Grade = Grade.A
            });
            context.SaveChanges();

            return context;
        }
    }
}

