using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using System.Net;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _sut;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly Mock<ILogger<CoursesController>> _loggerMock;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _envMock = new Mock<IWebHostEnvironment>();
            _loggerMock = new Mock<ILogger<CoursesController>>();
            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);
            _envMock.Setup(e => e.WebRootPath).Returns(_tempDir);
            _envMock.Setup(e => e.ContentRootPath).Returns(_tempDir);
            _sut = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
        }

        public void Dispose()
        {
            _sut.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
            {
                try { Directory.Delete(_tempDir, true); } catch { }
            }
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            var result = _sut.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _sut.Details(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var course = _context.Courses.First();

            var result = _sut.Details(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(course.CourseID, model.CourseID);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithDepartmentSelectList()
        {
            var result = _sut.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_sut.ViewBag.DepartmentID);
            Assert.IsType<Course>(result.Model);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidCourse_NoImage_RedirectsToIndex()
        {
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 9999,
                Title = "New Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _sut.Create(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.NotNull(_context.Courses.Find(9999));
        }

        [Fact]
        public void Create_Post_InvalidExtension_ReturnsViewWithError()
        {
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 8888,
                Title = "Bad Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var fileMock = CreateMockFormFile("test.exe", 1024);

            var result = _sut.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_sut.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_FileTooLarge_ReturnsViewWithError()
        {
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 7777,
                Title = "Large Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var fileMock = CreateMockFormFile("test.jpg", 6 * 1024 * 1024); // 6MB

            var result = _sut.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_sut.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_ValidImage_SavesFileAndRedirects()
        {
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 6666,
                Title = "With Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            var fileMock = CreateMockFormFile("material.png", 1024);

            var result = _sut.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var savedCourse = _context.Courses.Find(6666);
            Assert.NotNull(savedCourse);
            Assert.StartsWith("/Uploads/TeachingMaterials/", savedCourse.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _sut.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 5555, Title = "X", Credits = 3 };

            var result = _sut.Create(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _sut.Edit((int?)null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            var course = _context.Courses.First();

            var result = _sut.Edit((int?)course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal(course.CourseID, model.CourseID);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            var result = _sut.Edit((int?)99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidCourse_NoImage_RedirectsToIndex()
        {
            var course = _context.Courses.First();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = course.CourseID,
                Title = "Updated Title",
                Credits = course.Credits,
                DepartmentID = course.DepartmentID
            };

            var result = _sut.Edit(editedCourse, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidExtension_ReturnsViewWithError()
        {
            var course = _context.Courses.First();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedCourse = new Course
            {
                CourseID = course.CourseID,
                Title = course.Title,
                Credits = course.Credits,
                DepartmentID = course.DepartmentID
            };
            var fileMock = CreateMockFormFile("test.txt", 1024);

            var result = _sut.Edit(editedCourse, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_sut.ModelState.ContainsKey("teachingMaterialImage"));
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _sut.Delete(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithCourse()
        {
            var course = _context.Courses.First();

            var result = _sut.Delete(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            Assert.IsType<Course>(result.Model);
        }

        // --- DeleteConfirmed ---

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
        {
            var course = _context.Courses.First();
            var courseId = course.CourseID;

            var result = _sut.DeleteConfirmed(courseId) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Courses.Find(courseId));
        }

        // --- Helpers ---

        private static Mock<IFormFile> CreateMockFormFile(string fileName, long length)
        {
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns(fileName);
            fileMock.Setup(f => f.Length).Returns(length);
            var ms = new MemoryStream(new byte[Math.Min(length, 1024)]);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()))
                .Callback<Stream>(s => ms.CopyTo(s));
            return fileMock;
        }
    }
}

