using System.Net;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _sut;

        public DepartmentsControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _sut = new DepartmentsController(_context);
        }

        public void Dispose()
        {
            _sut.Dispose();
            _context.Dispose();
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithDepartments()
        {
            var result = _sut.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<Department>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _sut.Details(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithDepartment()
        {
            var dept = _context.Departments.First();

            var result = _sut.Details(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result.Model);
            Assert.Equal(dept.DepartmentID, model.DepartmentID);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            var result = _sut.Details(99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithInstructorSelectList()
        {
            var result = _sut.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_sut.ViewBag.InstructorID);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidDepartment_RedirectsToIndex()
        {
            var instructor = _context.Instructors.First();
            var dept = new Department
            {
                Name = "Science",
                Budget = 200000,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = instructor.ID
            };

            var result = _sut.Create(dept) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.True(_context.Departments.Any(d => d.Name == "Science"));
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _sut.ModelState.AddModelError("Name", "Required");
            var dept = new Department { Name = "X", Budget = 1000, StartDate = DateTime.Today };

            var result = _sut.Create(dept) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _sut.Edit(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithDepartment()
        {
            var dept = _context.Departments.First();

            var result = _sut.Edit(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result.Model);
            Assert.Equal(dept.DepartmentID, model.DepartmentID);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            var result = _sut.Edit(99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidDepartment_RedirectsToIndex()
        {
            var dept = _context.Departments.First();
            _context.Entry(dept).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var editedDept = new Department
            {
                DepartmentID = dept.DepartmentID,
                Name = "Updated English",
                Budget = dept.Budget,
                StartDate = dept.StartDate,
                InstructorID = dept.InstructorID,
                RowVersion = dept.RowVersion
            };

            var result = _sut.Edit(editedDept) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            _sut.ModelState.AddModelError("Name", "Required");
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "X",
                Budget = 1000,
                StartDate = DateTime.Today
            };

            var result = _sut.Edit(dept) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _sut.Delete(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, result.StatusCode);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithDepartment()
        {
            var dept = _context.Departments.First();

            var result = _sut.Delete(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            Assert.IsType<Department>(result.Model);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            var result = _sut.Delete(99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        // --- DeleteConfirmed ---

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
        {
            var dept = _context.Departments.First();
            var deptId = dept.DepartmentID;

            var result = _sut.DeleteConfirmed(deptId) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Departments.Find(deptId));
        }
    }
}

