using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _sut;

        public HomeControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _sut = new HomeController(_context);
        }

        public void Dispose()
        {
            _sut.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _sut.Index() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void About_ReturnsViewWithEnrollmentDateGroups()
        {
            var result = _sut.About() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
            Assert.NotEmpty(model);
            // We have 3 students with different enrollment dates
            Assert.True(model.All(g => g.StudentCount > 0));
        }

        [Fact]
        public void About_GroupsStudentsByEnrollmentDate()
        {
            var result = _sut.About() as ViewResult;
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);

            var totalStudents = model.Sum(g => g.StudentCount);
            Assert.Equal(3, totalStudents); // 3 seeded students
        }

        [Fact]
        public void Contact_ReturnsViewWithMessage()
        {
            var result = _sut.Contact() as ViewResult;

            Assert.NotNull(result);
            Assert.Equal("Your contact page.", _sut.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsView()
        {
            var result = _sut.Error() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewWithPermissionMessage()
        {
            var result = _sut.Unauthorized() as ViewResult;

            Assert.NotNull(result);
            Assert.Contains("permission", (string)_sut.ViewBag.Message);
        }
    }
}

