using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _sut;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.CreateSeeded();
            _sut = new NotificationsController(_context);
        }

        public void Dispose()
        {
            _sut.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Drain any notifications left from other tests (static queue)
            DrainNotificationQueue();

            var result = _sut.GetNotifications();

            Assert.NotNull(result);
            var value = result.Value;
            Assert.NotNull(value);
            // Verify it's a success response with count 0
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value));
            var countProp = value.GetType().GetProperty("count");
            Assert.Equal(0, (int)countProp.GetValue(value));
        }

        [Fact]
        public void GetNotifications_WithPendingNotifications_ReturnsNotifications()
        {
            DrainNotificationQueue();

            // Send notifications through the base controller's notification service
            var notificationService = new NotificationService();
            notificationService.SendNotification("Test", "1", "TestEntity", EntityOperation.CREATE, "TestUser");
            notificationService.SendNotification("Test", "2", "TestEntity2", EntityOperation.UPDATE, "TestUser");

            var result = _sut.GetNotifications();
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
            var countProp = value.GetType().GetProperty("count");
            Assert.True((int)countProp.GetValue(value) >= 1);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _sut.MarkAsRead(1);

            Assert.NotNull(result);
            var value = result.Value;
            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(value));
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _sut.Index() as ViewResult;

            Assert.NotNull(result);
        }

        private void DrainNotificationQueue()
        {
            var service = new NotificationService();
            while (service.ReceiveNotification() != null) { }
        }
    }
}

