using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            var student = new Student { FirstMidName = "John", LastName = "Doe" };

            Assert.Equal("Doe, John", student.FullName);
        }

        [Theory]
        [InlineData("Alice", "Smith", "Smith, Alice")]
        [InlineData("", "Empty", "Empty, ")]
        [InlineData("Bob", "", ", Bob")]
        public void FullName_VariousCombinations(string first, string last, string expected)
        {
            var instructor = new Instructor
            {
                FirstMidName = first,
                LastName = last,
                HireDate = DateTime.Today,
                CourseAssignments = new List<CourseAssignment>()
            };

            Assert.Equal(expected, instructor.FullName);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_WithRequestId_ReturnsTrue()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };

            Assert.True(model.ShowRequestId);
        }

        [Theory]
        [InlineData(null)]
        [InlineData("")]
        public void ShowRequestId_NullOrEmpty_ReturnsFalse(string requestId)
        {
            var model = new ErrorViewModel { RequestId = requestId };

            Assert.False(model.ShowRequestId);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_DefaultValues()
        {
            var notification = new Notification();

            Assert.Equal(0, notification.Id);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void Notification_PropertiesCanBeSet()
        {
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "New Student created",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = true,
                ReadAt = now
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student created", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.True(notification.IsRead);
            Assert.Equal(now, notification.ReadAt);
        }
    }

    public class EntityOperationTests
    {
        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }
    }

    public class GradeTests
    {
        [Fact]
        public void Grade_HasExpectedValues()
        {
            Assert.Equal(0, (int)Grade.A);
            Assert.Equal(1, (int)Grade.B);
            Assert.Equal(2, (int)Grade.C);
            Assert.Equal(3, (int)Grade.D);
            Assert.Equal(4, (int)Grade.F);
        }
    }
}

