[Fact]
public void Index_WithCourseId_PopulatesEnrollments()
{
    // Use a fresh context with minimal data to avoid InMemory provider fixup duplicates
    var dbName = Guid.NewGuid().ToString();
    using var ctx = TestDbContextFactory.Create(dbName);

    var instructor = new Instructor
    {
        FirstMidName = "Solo",
        LastName = "Teacher",
        HireDate = new DateTime(2000, 1, 1),
        CourseAssignments = new List<CourseAssignment>()
    };
    ctx.Instructors.Add(instructor);
    ctx.SaveChanges();

    var dept = new Department
    {
        Name = "Dept",
        Budget = 100000,
        StartDate = new DateTime(2007, 9, 1),
        InstructorID = instructor.ID
    };
    ctx.Departments.Add(dept);
    ctx.SaveChanges();

    var course = new Course
    {
        CourseID = 5001,
        Title = "Solo Course",
        Credits = 3,
        DepartmentID = dept.DepartmentID,
        Enrollments = new List<Enrollment>(),
        CourseAssignments = new List<CourseAssignment>()
    };
    ctx.Courses.Add(course);
    ctx.SaveChanges();

    ctx.CourseAssignments.Add(new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID });
    ctx.SaveChanges();

    var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Today };
    ctx.Students.Add(student);
    ctx.SaveChanges();
    ctx.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A });
    ctx.SaveChanges();

    using var controller = new InstructorsController(ctx);
    var result = controller.Index(instructor.ID, course.CourseID) as ViewResult;

    var model = Assert.IsType<InstructorIndexData>(result.Model);
    Assert.NotNull(model.Enrollments);
    Assert.Single(model.Enrollments);
}

